import json,sys,time
from pathlib import Path
from copy import deepcopy
import httpx
from seekra.context import build_context
from seekra.session import Session
from seekra.cli import read_config
from seekra.models import DeepSeekModel
from seekra.runtime import CancellationToken
p=Path(sys.argv[1]); r=json.loads((p/'research-baseline.json').read_text(encoding='utf-8'))
def js(x): return json.dumps(x,ensure_ascii=False)
original=r['requests'][-1]; full=deepcopy(original['messages']); full[0]['content']=full[0]['content'].split('\n较旧任务可能已整组移出')[0]
by_id={t['call_id']:t['result'] for t in r['tool_stats']}; ids={}
for request in r['requests']:
 for m in request['messages']:
  if m['role']=='tool':
   payload=json.loads(m['content'])
   if payload.get('offloaded'): ids[m['tool_call_id']]=payload['record_id']
for m in full:
 if m['role']=='tool': m['content']=js(by_id[m['tool_call_id']])
def trim(q):
 q=deepcopy(q)
 for k in ['processing','search_parameters']: q.pop(k,None)
 if q.get('operation')=='tavily_search':q.pop('query',None)
 if q.get('requested_url')==q.get('url'):q.pop('requested_url',None)
 if q.get('final_url','absent') is None:q.pop('final_url',None)
 return q
out={}; cfg=read_config(Path('.env'))
with httpx.Client() as client:
 for arm in ['baseline','large','slim']:
  messages=deepcopy(full); s=Session()
  for i,m in enumerate(messages):
   if m['role']=='tool':
    if arm=='slim':m['content']=js(trim(json.loads(m['content'])))
    s.records.append({'id':ids.get(m['tool_call_id'],str(1000+i)),'kind':'tool_completed','call_id':m['tool_call_id'],'result':m['content']})
  s.records.sort(key=lambda x:int(x['id']))
  selected,info=build_context(messages,original['tools'],s,240000 if arm=='large' else 120000)
  if arm=='baseline': assert selected==original['messages'],'baseline reconstruction differs'
  usage=[]; start=time.monotonic()
  result=DeepSeekModel(client,cfg['DEEPSEEK_MODEL'],cfg['DEEPSEEK_API_KEY']).generate(selected,original['tools'],on_content=lambda x:None,on_usage=usage.append,cancel=CancellationToken())
  out[arm]={'context':info,'request':{**original,'messages':selected},'response':result.message,'finish_reason':result.finish_reason,'usage':usage,'seconds':round(time.monotonic()-start,2),'trigger_present':'An object will be made immortal' in js(selected)}
  (p/'checkpoint.json').write_text(js(out),encoding='utf-8')
  print(js({'arm':arm,**info,'trigger_present':out[arm]['trigger_present'],'finish_reason':result.finish_reason}),flush=True)

