import json,sys,time,hashlib,os
from pathlib import Path
from copy import deepcopy
import httpx
from seekra.cli import read_config
from seekra.session import Session
from seekra.tools import default_registry
from seekra.models import DeepSeekModel
from seekra.agent import execute_run
OUT=Path(sys.argv[1]); ARM=sys.argv[2]; CASE=sys.argv[3]
def js(v): return json.dumps(v,ensure_ascii=False)
def sha(v): return hashlib.sha256(js(v).encode()).hexdigest()
def trim(p):
    q=deepcopy(p)
    for k in ['processing','search_parameters']: q.pop(k,None)
    if q.get('operation')=='tavily_search': q.pop('query',None)
    if q.get('requested_url')==q.get('url'): q.pop('requested_url',None)
    if q.get('final_url','absent') is None: q.pop('final_url',None)
    return q
s=Session(); expected={}
if CASE=='archive':
    old=json.loads(Path('evals/evidence/context-history-20260927.json').read_text(encoding='utf-8'))
    source=old['probe_source']; setup=source[source.index("s=Session();"):source.index('trace=[];')]
    def dump(x): return js(x)
    def call(i,name,args): return {'id':i,'type':'function','function':{'name':name,'arguments':js(args)}}
    exec(setup)
else:
    question='请只依据 Python 3.13 官方文档，核查 free-threaded CPython 的六个方面：如何选择或构建、运行时怎样确认 GIL 是否启用、扩展模块可能怎样影响 GIL、mimalloc 的要求、线程安全的边界、对象 immortalization 的条件与内存影响。逐项给出结论和实际依据的官方页面 URL；区分构建支持、运行时状态和线程安全，不混用其他版本。请自主搜索和读正文，核查完成后回答，无需向我申请继续确认。'
config=read_config(Path('.env')); logs=[]; requests=[]; tool_stats=[]
cachepath=OUT/'http-cache.json'; cache=json.loads(cachepath.read_text(encoding='utf-8')) if cachepath.exists() else {}
class Transport(httpx.BaseTransport):
    def __init__(self): self.inner=httpx.HTTPTransport()
    def handle_request(self,request):
        if request.url.host=='api.tavily.com':
            key=sha([str(request.url),request.content.decode()])
            if key in cache:
                x=cache[key]; return httpx.Response(x['status'],json=x['json'],request=request)
            response=self.inner.handle_request(request); response.read()
            try: data=response.json()
            except ValueError: return response
            cache[key]={'status':response.status_code,'json':data,'url':str(request.url),'request':json.loads(request.content)}
            cachepath.write_text(js(cache),encoding='utf-8')
            return response
        return self.inner.handle_request(request)
    def close(self): self.inner.close()
def capture(req):
    if req.url.host=='api.deepseek.com': requests.append(json.loads(req.content))
base_reader=s.read_record
if ARM=='slim':
    def read(entry_id,start=0,limit=24000):
        original=base_reader(entry_id,start=0,limit=1)
        e=s.records[int(entry_id)-1]
        if e['kind']!='tool_completed': return base_reader(entry_id,start=start,limit=limit)
        if type(start) is not int or start<0 or type(limit) is not int or not 1<=limit<=24000: raise ValueError('读取范围不合法')
        text=js(trim(json.loads(e['result'])))
        if start>=len(text): raise ValueError('起点超出记录范围')
        end=min(start+limit,len(text))
        return {**original,'content_kind':'tool_result','content':text[start:end],'status':'success' if start==0 and end==len(text) else 'partial','start':start,'end':end,'total_characters':len(text),'next_start':end if end<len(text) else None}
    s.read_record=read
with httpx.Client(transport=Transport(),event_hooks={'request':[capture]}) as client:
    registry=default_registry(client,config['TAVILY_API_KEY'],s); execute=registry.execute
    def wrapped(c,p,k):
        raw=execute(c,p,k); payload=json.loads(raw); lean=trim(payload); returned=js(lean) if ARM=='slim' else raw
        snippets=sum(len(x.get('content','')) for x in payload.get('results',[]))
        body=len(payload.get('content','')) if isinstance(payload.get('content'),str) else 0
        tool_stats.append({'call_id':c['id'],'operation':c['function']['name'],'arguments':json.loads(c['function']['arguments']),'original_chars':len(raw),'slim_chars':len(js(lean)),'returned_chars':len(returned),'snippet_chars':snippets,'body_chars':body,'other_chars':len(raw)-snippets-body,'result':json.loads(returned)})
        return returned
    registry.execute=wrapped
    def event(name,**kw):
        if name in {'context','tool_call','end','model_call'}:
            logs.append({'event':name,**kw}); print(js({'case':CASE,'arm':ARM,**logs[-1]}),flush=True)
    start=time.monotonic()
    result=execute_run(question,model=DeepSeekModel(client,config['DEEPSEEK_MODEL'],config['DEEPSEEK_API_KEY']),registry=registry,session=s,max_iterations=12,max_context_chars=240000 if ARM=='large' else 120000,on_event=event)
record={'case':CASE,'arm':ARM,'question':question,'model':config['DEEPSEEK_MODEL'],'limit':240000 if ARM=='large' else 120000,'seconds':round(time.monotonic()-start,2),'status':result.status,'error':result.error,'answer':result.answer,'usage':s.usage_totals(),'tool_stats':tool_stats,'trace':logs,'requests':requests,'expected':expected,'codes_correct':sum(v in (result.answer or '') for v in expected.values()) if expected else None}
text=js(record)
for key in ('DEEPSEEK_API_KEY','TAVILY_API_KEY'): text=text.replace(config[key],'[REDACTED]')
(OUT/f'{CASE}-{ARM}.json').write_text(text,encoding='utf-8')
print(js({k:v for k,v in record.items() if k not in {'tool_stats','trace','requests','expected','question'}}),flush=True)
